import { bar } from 'axylo';

const QUARTER = /^\s*(\d{4})\s*Q([1-4])\s*$/i;

/** Sort key for labels such as '2025 Q3'; labels that do not match sort after the rest, in input order. */
function quarterKey(label) {
  const match = QUARTER.exec(String(label));
  return match ? Number(match[1]) * 4 + Number(match[2]) - 1 : Number.POSITIVE_INFINITY;
}

/**
 * The bar options for the rows of data.json. Exported so the same options can be checked with
 * axylo's validate() in Node, where render() cannot run.
 */
export function chartOptions(data) {
  // Quarters are categories in Axylo 1.0, and categories keep the order in which they first appear,
  // so put the rows in calendar order. Sort a copy: the caller's array is left as it was, and the
  // row objects are the caller's own, so events still hand back their rows.
  const rows = [...data].sort((a, b) => quarterKey(a.quarter) - quarterKey(b.quarter));

  return {
    title: 'Quarterly sales by region',
    data: rows,
    // Ordered categories: labels may be thinned if they do not fit.
    x: { field: 'quarter', ordered: true },
    // Wide rows: one field per region, side by side (layout 'grouped' is the default).
    // The values arrive as decimal strings, so declare the conversion.
    y: [
      { field: 'north', label: 'North', parse: 'number' },
      { field: 'central', label: 'Central', parse: 'number' },
      { field: 'west', label: 'West', parse: 'number' },
    ],
    // With several value fields the shared axis is titled by the `value` message ("Value").
    messages: { value: 'Sales' },
  };
}

/** Draws the chart into `element` and returns the Axylo chart handle. */
export default function render(element, data) {
  return bar(element, chartOptions(data));
}

