// Self-check in Node, as docs/diagnostics.html "validate() in Node and in tests" describes.
import { readFileSync } from 'node:fs';
import { validate } from 'axylo';
import render, { chartOptions } from './chart.js';

const data = JSON.parse(readFileSync(new URL('./data.json', import.meta.url), 'utf8'));
const before = JSON.stringify(data);
const opts = chartOptions(data);

console.log('default export:', typeof render, render.name, 'arity', render.length);
console.log('x order:', opts.data.map(r => r.quarter).join(' | '));
console.log('input array unchanged:', JSON.stringify(data) === before);
console.log('rows are the caller\'s objects:', opts.data.every(r => data.includes(r)));

const problems = validate('bar', opts);
console.log('diagnostics:', problems.length);
for (const d of problems) console.log(' ', d.code, d.level, d.field ?? '', d.message);

const blocking = problems.filter(d => d.level !== 'hint');
if (blocking.length > 0) process.exitCode = 1;

